import React from "react";
import "./Header.css";

function Header() {
  return (
    <header className="header">
      <div className="header-text">
        <h1>Hello, I'm <span className="name">Yvette Niyogitangaza</span></h1>
        <p>Aspiring Data Scientist & Web Developer</p>
        <a
          href="/cv.pdf"
          download
          className="cv-button"
        >
          📄 Download CV
        </a>
      </div>
    </header>
  );
}

export default Header;
